@callback
def async_want(
    hass: HomeAssistant, entry: ConfigEntry, lock_entity_id: str, slot: int, pin: Want
) -> None:
    """Set what ``slot`` should hold on a lock ``entry`` holds, if it owns the slot."""
    if not async_owns_slot(hass, entry, lock_entity_id, slot):
        return
    registry = lock_registry(hass)
    if (worker := registry.worker(lock_entity_id)) is None:
        return
    port = worker.port
    address = pin_address(slot)
    current = worker.slots.get(address)
    if (
        current is not None
        and current.want == pin
        and not current.release
        and slot not in port.releasing
    ):
        return  # nothing new to tell the lock: no sync to queue
    port.releasing.discard(slot)
    hass.data[DATA][GIVEN_UP_KEY].pop((lock_entity_id, slot), None)
    try:
        registry.want(lock_entity_id, entry.entry_id, address, pin)
    except (KeyError, SlotTaken) as err:
        _LOGGER.error(
            "%s: cannot set slot %s on %s: %s",
            entry.entry_id,
            slot,
            lock_entity_id,
            err,
        )
        return
    # A sync is queued: views show it syncing now, not once a job finishes.
    async_dispatcher_send(hass, signal_lock_changed(lock_entity_id))


@callback
def async_give_up(
    hass: HomeAssistant,
    entry: ConfigEntry,
    lock_entity_id: str,
    slot: int,
    *,
    clear: bool = True,
) -> None:
    """
    Stop managing ``slot`` on a lock ``entry`` holds.

    Cleared on the way out unless ``clear`` is off (a user handed off with
    their code left programmed): a release, which goes on after the entry
    unloads.
    """
    # No longer this entry's slot: a conflict over it is over.
    async_delete_issue(
        hass, DOMAIN, slot_conflict_issue_id(entry.entry_id, lock_entity_id, slot)
    )
    registry = lock_registry(hass)
    if (worker := registry.worker(lock_entity_id)) is None:
        return
    port = worker.port
    if clear and not worker.answered:
        # A lock with no PIN support holds no codes, unless it answered an
        # earlier run that wrote some: no clear to wait on. Every other
        # failed setup (a node dead at boot, a slot count not known until a
        # re-interview, a retry under way) may hold codes, and the clear waits
        # for it to recover -- except one that crashed, which nothing retries
        # short of a reload: that clear would wait forever.
        if port.provider.pin_unsupported and not worker.answered_ever:
            clear = False
        elif port.setup_crashed:
            _LOGGER.warning(
                "Slot %s on %s was given up without clearing it: the lock's "
                "setup failed with an unexpected error, so nothing can be sent "
                "to it. Any code left in that slot stays on the lock",
                slot,
                lock_entity_id,
            )
            clear = False
    try:
        if clear:
            _begin_release(hass, port, slot)
            registry.give_up(lock_entity_id, entry.entry_id, slot)
            hass.data[DATA][GIVEN_UP_KEY][lock_entity_id, slot] = (
                entry.entry_id,
                worker,
            )
        else:
            registry.unclaim(lock_entity_id, entry.entry_id, slot)
            if (store := hass.data[DATA].get(STORE_KEY)) is not None:
                store.forget_slot(port.provider.lock.id, slot)
    except KeyError:
        return  # never held: nothing to give up
    async_hand_off(hass, entry, lock_entity_id, [slot])
            # A provider that reads the whole lock in one call tells of every
            # code on it: one it no longer tells of is gone (deleted at the
            # keypad, say). What it said nothing about stays as it was.
            self.others = {
                **{slot: seen for slot, seen in self.others.items() if slot in silent},
                **heard,
            }
        else:
            # One that walks the slots asked for says nothing of the rest.
            self.others.update(heard)
        self._answered = self._answered or bool(readings)
        return readings

    def _duplicate_of(self, slot: int, pin: str) -> int | None:
        """
        Return another slot ``pin`` is on, or is wanted on; None if none.

        A tracked slot counts by what it wants (one on its way to another
        PIN, or out, does not); any other slot by what the lock said of it.
        """
        tracked = (
            {}
            if self.worker is None
            else {
                address.user_ref: current
                for address, current in self.worker.slots.items()
                if address.credential_type is CredentialType.PIN
            }
        )
        for other, held in self.others.items():
            if other != slot and other not in tracked and held == Holds(pin):
                return other
        return next(
            (
                other
                for other, current in tracked.items()
                if other != slot and current.want == pin and not current.release
            ),
            None,
        )

    def release(self, slot: int, *, written: bool) -> None:
        """
        Make ``slot``'s next clear a release.

        ``written``: the store shows a PIN Lock Code Manager wrote there.
        Taken now: the worker forgets what it wrote as it sends the clear.
        """
        self.releasing.add(slot)
        if written:
            self._written.add(slot)
        else:
            self._written.discard(slot)

    async def write(self, slot: CredentialAddress, value: str | None) -> bool | None:
        """Put ``value`` at ``slot``, or clear it (see ``_write``), timed for the logs."""
            # Masked: the ``deobfuscate_log`` action decodes it from here.
            _LOGGER.debug(
                "Setting usercode on %s slot %s (pin=%s, source=%s)",
                provider.lock.entity_id,
                slot,
                provider.mask_pin(pin, slot),
                "sync",
            )
        try:
            if pin is None and slot in self.releasing:
                await provider.async_release_managed_slot(
                    slot, written=slot in self._written
                )
            elif pin is None:
                # A clear that found nothing says nothing about what is there.
                return await provider.async_clear_usercode(slot)
            else:
                await self._capacity(slot)
                if (other := self._duplicate_of(slot, pin)) is not None:
                    # Two users sharing a PIN: whoever types it opens the door
                    # as the other, and turning one off leaves it working.

